  "summary": [
    "Anchor anchored to historical 2/3 majority rate in Hungary's post-1990 elections (~0.44 baseline).",
    "Structural bias in Hungary's electoral system weighs against a 2/3 majority (strong downward pressure).",
    "Opposition consolidation around TISZA offers a nontrivial upward path if unity translates into seat gains.",
    "Polling volatility and mixed market signals keep the outcome uncertain, supporting a calibrated range of 0.55–0.75."
  ],
  "confidence": "high",
  "narrative": "Starting from the historical base-rate for a 2/3 majority, the analysis applies downward pressure from the electoral system while lifting slightly from the possibility of opposition unity and selective market signals. The calibrated result implies a meaningful but not guaranteed chance of a constitutional majority, centered at 0.65 with a 0.55–0.75 interval.",
  "justification": {
    "anchor": {
      "probability": 0.44,
      "basis": "Historical base-rate: 4 of 9 post-1990 Hungarian elections produced a 2/3 majority; current reference class retains similar mechanics (106 SMD + 93 PR seats)."
    },
    "factor_updates": [
      {
        "factor": "Electoral-system bias toward incumbents (winner compensation, single-member districts, and cardinal-law constraints)",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Analyses consistently flag structural advantages for the ruling bloc that compress the probability of a 2/3 outcome even with favorable votes."
      },
      {
        "factor": "Opposition consolidation around TISZA",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Polls and expert commentary suggest growing unity around TISZA could translate votes into seats, raising odds toward the 133-seat threshold."
      },
      {
        "factor": "Polling volatility and divergent forecasts",
        "direction": "neutral",
        "magnitude": "moderate",
        "rationale": "Evidence of mixed signals across polls reduces directional confidence and supports a calibrated probability rather than a clear forecast."
      },
      {
        "factor": "Prediction-market signals and market uncertainty",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Some markets price the opposition ahead in certain measures; though fragile, this adds nonzero upward pressure on the probability."
      },
      {
        "factor": "Historical base-rate context and structural constraints",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Reaffirms the anchor and calibrates the assessment by reminding that 2/3 outcomes are not the norm and require favorable alignment of conditions."
      }
    ],
    "synthesis_rationale": "The posterior probability of 0.65 is obtained by starting with the 0.44 anchor from the reference class and applying the five moderate-to-strong updates with corresponding directions. Calibrated weighting leans toward modest upward risk from opposition unity and market signals but remains tempered by structural headwinds, resulting in a 0.55–0.75 credible range."
  }
}

